CREATE TABLE IF NOT EXISTS regions (id TEXT PRIMARY KEY, name TEXT NOT NULL, jurisdiction TEXT NOT NULL, geometry TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY, region_id TEXT NOT NULL, provider TEXT NOT NULL, source_scene_ids TEXT NOT NULL, acquisition_start TEXT, acquisition_end TEXT, status TEXT NOT NULL, quality TEXT NOT NULL, provenance TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS changes (id TEXT PRIMARY KEY, region_id TEXT, geometry TEXT NOT NULL, area_hectares REAL NOT NULL, baseline_date TEXT NOT NULL, comparison_date TEXT NOT NULL, disturbance_type TEXT NOT NULL, score REAL, status TEXT NOT NULL, provenance TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS forecasts (id TEXT PRIMARY KEY, region_id TEXT NOT NULL, origin TEXT NOT NULL, horizon_days INTEGER NOT NULL, status TEXT NOT NULL, risk_score REAL, provenance TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incidents (id TEXT PRIMARY KEY, change_id TEXT, wildfire_id TEXT, status TEXT NOT NULL, title TEXT NOT NULL, geometry TEXT NOT NULL, evidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wildfire_observations (id TEXT PRIMARY KEY, geometry TEXT NOT NULL, observed_at TEXT NOT NULL, observation_type TEXT NOT NULL, confidence REAL, source TEXT NOT NULL, status TEXT NOT NULL, evidence TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS authorizations (id TEXT PRIMARY KEY, authority TEXT NOT NULL, project_identifier TEXT, project_name TEXT, status TEXT NOT NULL, geometry TEXT, dates TEXT NOT NULL, source_url TEXT, evidence TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS authorization_assessments (id TEXT PRIMARY KEY, change_id TEXT NOT NULL, status TEXT NOT NULL, candidate_ids TEXT NOT NULL, rationale TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL, progress REAL NOT NULL, result TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_role TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, channel TEXT NOT NULL, recipient TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, provider_response TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS simulations (id TEXT PRIMARY KEY, region_id TEXT NOT NULL, status TEXT NOT NULL, claim_type TEXT NOT NULL, horizon_days INTEGER NOT NULL, mode TEXT NOT NULL, geometry TEXT NOT NULL, assumptions TEXT, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS impact_assessments (id TEXT PRIMARY KEY, incident_id TEXT NOT NULL, status TEXT NOT NULL, claim_type TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS energy_predictions (id TEXT PRIMARY KEY, status TEXT NOT NULL, claim_type TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY, incident_id TEXT NOT NULL, format TEXT NOT NULL, path TEXT NOT NULL, created_at TEXT NOT NULL);
